#include <bits/stdc++.h>
using namespace std;
struct Table{uint32_t G,W,S,p;vector<uint16_t>v;string path;uint16_t coeff(int r,int g,int s)const{return v[((size_t)r*G+g-1)*(S+1)+s];}};
Table loadt(const string&path){ifstream f(path,ios::binary);if(!f)throw runtime_error("cannot open "+path);Table t;t.path=path;f.read((char*)&t.G,4);f.read((char*)&t.W,4);f.read((char*)&t.S,4);f.read((char*)&t.p,4);size_t n=(size_t)(t.W+1)*t.G*(t.S+1);t.v.resize(n);f.read((char*)t.v.data(),2*n);if(!f)throw runtime_error("short table "+path);return t;}
int main(int argc,char**argv){if(argc<7){cerr<<"usage: check_modular_cover G Gamma n0 n1 uncovered.tsv table...\n";return 2;}int G=stoi(argv[1]),Gamma=stoi(argv[2]),n0=stoi(argv[3]),n1=stoi(argv[4]);string up=argv[5];vector<Table>T;for(int i=6;i<argc;i++)T.push_back(loadt(argv[i]));size_t width=(size_t)n1-n0+1,total=(size_t)G*width,remaining=total;vector<uint8_t>ok(total);vector<unsigned long long>cnt(T.size());for(size_t ti=0;ti<T.size();ti++){auto&t=T[ti];if((int)t.G<G)throw runtime_error("G too small in "+t.path);for(int n=n0;n<=n1;n++){int q=n/(int)t.p;if(q<0||q>=Gamma)continue;int r=Gamma-q;if(r<0||r>(int)t.W)continue;int s=n-q*(int)t.p;if(s<0||s>(int)t.S)continue;size_t b=(size_t)(n-n0)*G;for(int g=1;g<=G;g++){size_t pos=b+g-1;if(!ok[pos]&&t.coeff(r,g,s)){ok[pos]=1;cnt[ti]++;remaining--;}}}cerr<<"after p="<<t.p<<": remaining="<<remaining<<"\n";if(!remaining)break;}ofstream out(up);out<<"g\tn\n";for(int n=n0;n<=n1;n++){size_t b=(size_t)(n-n0)*G;for(int g=1;g<=G;g++)if(!ok[b+g-1])out<<g<<'\t'<<n<<'\n';}cout<<"total="<<total<<" covered="<<total-remaining<<" remaining="<<remaining<<"\n";for(size_t i=0;i<T.size();i++)cout<<"p="<<T[i].p<<" first="<<cnt[i]<<"\n";return remaining?1:0;}
